function hhParse(text){
  var map={}, lines=String(text||'').split(/\n+/);
  for(var i=0;i<lines.length;i++){
    var l=lines[i].trim(); if(!l) continue;
    var c=l.indexOf(':');
    if(c<0) continue;
    var k=l.slice(0,c).trim(), v=l.slice(c+1).trim();
    map[k.toLowerCase()]=v;
  }
  return map;
}
var HH_CHECKS=[
  {name:'Strict-Transport-Security', key:'strict-transport-security', sev:'高', test:function(v){ return /max-age=\d+/.test(v) && !/max-age=0/.test(v); }, advice:'建议 max-age≥31536000 并加 includeSubDomains'},
  {name:'Content-Security-Policy', key:'content-security-policy', sev:'高', test:function(v){return !!v;}, advice:'建议定义 default-src 并尽量收紧'},
  {name:'X-Frame-Options', key:'x-frame-options', sev:'中', test:function(v){return /^(deny|sameorigin)$/i.test(v);}, advice:'设为 DENY 或 SAMEORIGIN 防点击劫持'},
  {name:'X-Content-Type-Options', key:'x-content-type-options', sev:'中', test:function(v){return /^nosniff$/i.test(v);}, advice:'设为 nosniff'},
  {name:'Referrer-Policy', key:'referrer-policy', sev:'中', test:function(v){return !!v;}, advice:'建议 no-referrer 或 strict-origin-when-cross-origin'},
  {name:'Permissions-Policy', key:'permissions-policy', sev:'中', test:function(v){return !!v;}, advice:'限制摄像头/麦克风/地理位置等敏感特性'},
  {name:'Cross-Origin-Opener-Policy', key:'cross-origin-opener-policy', sev:'中', test:function(v){return /^(same-origin|same-origin-allow-popups)$/i.test(v);}, advice:'设为 same-origin 缓解 XS-leaks'},
  {name:'Cross-Origin-Resource-Policy', key:'cross-origin-resource-policy', sev:'低', test:function(v){return /^(same-origin|same-site|cross-origin)$/i.test(v);}, advice:'设为 same-origin 防止跨源资源加载'}
];
function hhAnalyze(text){
  var map=hhParse(text), results=[], score=0;
  for(var i=0;i<HH_CHECKS.length;i++){
    var c=HH_CHECKS[i], v=map[c.key]||'', present=!!v, pass=present && c.test(v);
    var w = c.sev==='高'?16 : c.sev==='中'?12 : 8;
    if(pass) score+=w;
    results.push({name:c.name, present:present, pass:!!pass, value:v, severity:c.sev, weight:w, advice:c.advice});
  }
  score=Math.min(100, score);
  var grade = score>=90?'A':score>=75?'B':score>=60?'C':score>=40?'D':'F';
  return { score:score, max:100, grade:grade, results:results };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { hhParse:hhParse, hhAnalyze:hhAnalyze, HH_CHECKS:HH_CHECKS };
}
if (typeof window !== 'undefined') {
  window.HttpHeadersForgePure = { hhParse:hhParse, hhAnalyze:hhAnalyze, HH_CHECKS:HH_CHECKS };
}
